import * as React from 'react';

export type StatusTone = 'success' | 'warning' | 'error' | 'neutral' | 'brand';

export interface CrmStatusPillProps {
  children: React.ReactNode;
  variant?: StatusTone;
  withDot?: boolean;
}

const tones: Record<StatusTone, string> = {
  success: 'border-success/20 bg-success-subtle text-success',
  warning: 'border-warning/25 bg-warning-subtle text-warning-foreground',
  error: 'border-destructive/20 bg-destructive-subtle text-destructive',
  neutral: 'border-border bg-muted text-muted-foreground',
  brand: 'border-primary/20 bg-accent text-accent-foreground'
};

/** Pipeline status pill for CRM tables and detail headers. */
export function CrmStatusPill({ children, variant = 'success', withDot = true }: CrmStatusPillProps) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 text-xs font-medium ${tones[variant]}`}
    >
      {withDot ? <span aria-hidden className="h-1.5 w-1.5 rounded-sm bg-current" /> : null}
      {children}
    </span>
  );
}

import * as React from 'react';
import { CrmStatusPill } from '../components/status-pill';

/** Preview fixture rendered by the catalogue. */
export default function CrmStatusPillPreview() {
  return (
    <div className="flex flex-wrap gap-2">
      <CrmStatusPill variant="success">Qualified</CrmStatusPill>
      <CrmStatusPill variant="warning">Needs follow-up</CrmStatusPill>
      <CrmStatusPill variant="error">Churn risk</CrmStatusPill>
    </div>
  );
}
